import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Coding style","description":"","frontmatter":{},"headers":[],"relativePath":"dev/coding-style.md","filePath":"dev/coding-style.md"}'),l={name:"dev/coding-style.md"};function r(n,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="coding-style" tabindex="-1">Coding style <a class="header-anchor" href="#coding-style" aria-label="Permalink to &quot;Coding style&quot;">​</a></h1><p>The tree is self-consistent; match it.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><ul><li>C11 (<code>-std=gnu11</code>), 4-space indent, K&amp;R braces, no tabs in .c/.h.</li><li>Types: the kernel&#39;s fixed-width set (<code>u8/u16/u32/u64/s8/...</code>, <code>types.h</code>) - not uint8_t spellings.</li><li>One declaration per line where the type matters; initialize what you can.</li><li>Every file opens with the SPDX + copyright comment block and a Purpose paragraph that says WHY the file exists. Future readers (and the docs generator) rely on it.</li><li>Function comments: contract, arguments, return codes - especially every negative return.</li><li>Error handling: check, report with a clear message, and unwind - never leak a half-initialized device registration.</li></ul><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><ul><li><code>.S</code> files (preprocessed): boot.S and the arch trampolines are the reference. Comment the ABI at every entry point.</li></ul><h2 id="shell-commands" tabindex="-1">Shell commands <a class="header-anchor" href="#shell-commands" aria-label="Permalink to &quot;Shell commands&quot;">​</a></h2><ul><li>Register with <code>shell_register_command_ex</code> + the work-package tag so <code>help -w</code> stays truthful.</li><li>One-line help, <code>usage:</code> printout on argument errors, exit non-zero on failure.</li><li>ASCII only.</li></ul><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li>Files: <code>kernel/&lt;area&gt;/core_&lt;thing&gt;.c</code>, <code>drivers/&lt;bus&gt;/driver_&lt;hw&gt;.c</code>, <code>shell/shell_cmds_&lt;domain&gt;.c</code>, <code>fs/fs_&lt;fs&gt;.c</code> - the tree&#39;s layout IS the taxonomy (the docs generator groups by it).</li><li>Symbols: <code>&lt;module&gt;_&lt;verb&gt;_&lt;object&gt;</code> (e.g. <code>driver_block_flush</code>, <code>klog_write</code>, <code>ota_ab_install</code>). Static helpers stay file-local.</li><li>All-caps constants with a module prefix (<code>OC_MB2_TAG_END</code>, <code>SHELL_MAX_COMMANDS</code>).</li></ul><h2 id="limits-are-part-of-the-design" tabindex="-1">Limits are part of the design <a class="header-anchor" href="#limits-are-part-of-the-design" aria-label="Permalink to &quot;Limits are part of the design&quot;">​</a></h2><p>When you add a bounded table, the limit constant carries a comment explaining the number (see <code>SHELL_MAX_COMMANDS</code> in shell.h - the history of 232-&gt;256 is documented at the definition). Keep that discipline: the next person tuning it needs the story.</p><h2 id="what-not-to-do" tabindex="-1">What not to do <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;What not to do&quot;">​</a></h2><ul><li>No dead code &quot;for later&quot; - delete it; git remembers.</li><li>No silent truncation - refuse with a message (alias values are the model: stored in full or refused).</li><li>No <code>// TODO</code> without a BUG- number or a work-package reference.</li><li>No new third-party code: the tree is original, Apache 2.0, and stays that way.</li></ul>',14)])])}const g=t(l,[["render",r]]);export{m as __pageData,g as default};
